def verify_isbn(isbn: str) -> str:
    if not isbn or len(isbn) != 13 or not isbn.replace('-', '').isdigit():
        return "Invalid ISBN format"

    def calculate_checksum(isbn):
        weights = [1, 3, 1, 3, 1, 3, 1, 3, 1, 3, 1, 3]
        sum = 0
        for i in range(12):
            sum += int(isbn[i]) * weights[i]
        return (10 - (sum % 10)) % 10

    calculated_checksum = calculate_checksum(isbn)
    if calculated_checksum == int(isbn[-1]):
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + str(calculated_checksum)
        return corrected_isbn

