def generate_numbers(n, rules) -> int:
    if not rules:
        return 1  # If no rules, the number itself is considered unique

    # Convert the number to a set of digits for easy manipulation
    digits = set(str(n))
    queue = deque(digits)
    visited = set(digits)

    while queue:
        current = queue.popleft()
        if current in visited:
            continue
        visited.add(current)

        # Apply each rule to the current digit
        for rule in rules:
            if current[0] == rule[0]:
                new_digit = current[1]
                if new_digit not in visited:
                    queue.append(new_digit)
                    visited.add(new_digit)

    return len(visited)

