def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    left = 0
    right = n - 1
    count = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
            count += 1

    return count

